CREATE POLICY "Clients read their own deliverable files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'client-deliverables' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Admins read all deliverable files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'client-deliverables' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins upload deliverable files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'client-deliverables' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update deliverable files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'client-deliverables' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'client-deliverables' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete deliverable files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'client-deliverables' AND public.has_role(auth.uid(), 'admin'));